export const db=new Map(),calls=[];export async function get(k,o){calls.push({kind:'get',k,o});if(!db.has(k))return null;const value=db.get(k);if(Buffer.isBuffer(value)){return{statusCode:200,stream:new Response(value).body,blob:{contentType:'image/jpeg',size:value.length}}}if(value?.binary){const etag='"fixture-proof"';if(o?.headers?.['If-None-Match']===etag)return{statusCode:304,stream:null,blob:{etag}};return{statusCode:200,stream:new Response('PHOTO').body,blob:{contentType:'image/jpeg',size:5,etag}}}return{statusCode:200,stream:new Response(JSON.stringify(value)).body,blob:{}}}export async function put(k,v){db.set(k,Buffer.isBuffer(v)?v:JSON.parse(v));return{pathname:k}}export async function list({prefix}){calls.push({kind:'list',prefix});return{blobs:[...db.keys()].filter(k=>k.startsWith(prefix)).map(pathname=>({pathname})),hasMore:false}}export async function head(){}export async function del(k){db.delete(k)}
